Una suite que atrapa todo:

```js
test("todo válido", () => {
  expect(validarRegistro(validos)).toStrictEqual({});
});
test("nombre de solo espacios", () => {
  expect(validarRegistro({ ...validos, nombre: "   " })).toEqual({ nombre: "El nombre es obligatorio" });
});
test("correo sin punto", () => {
  expect(validarRegistro({ ...validos, correo: "ana@correo" })).toEqual({ correo: "El correo no es válido" });
});
test("18 años justos", () => {
  expect(validarRegistro({ ...validos, edad: 18 })).toEqual({});
});
test("contraseñas distintas", () => {
  expect(validarRegistro({ ...validos, confirmar: "secreta124" })).toEqual({ confirmar: "Las contraseñas no coinciden" });
});
test("todos los errores juntos", () => {
  const datos = { nombre: "", correo: "ana", edad: 15, clave: "corta", confirmar: "otra" };
  expect(Object.keys(validarRegistro(datos))).toEqual(["nombre", "correo", "edad", "clave", "confirmar"]);
});
```
